pub fn parse_n_from_env() -> i32 {
    match std::env::args().nth(1) {
        Some(raw) => match parse_i32_prefix(&raw) {
            Ok(value) => value,
            Err(ParseError::Invalid) => abort_with_stoi("std::invalid_argument"),
            Err(ParseError::OutOfRange) => abort_with_stoi("std::out_of_range"),
        },
        None => 11,
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ParseError {
    Invalid,
    OutOfRange,
}

fn parse_i32_prefix(input: &str) -> Result<i32, ParseError> {
    let trimmed = input.trim_start_matches(|ch: char| ch.is_ascii_whitespace());
    let bytes = trimmed.as_bytes();
    let mut index = 0usize;
    let mut negative = false;

    if let Some(&byte) = bytes.get(index) {
        match byte {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let mut saw_digit = false;
    let mut value = 0i64;
    let limit = if negative {
        2_147_483_648i64
    } else {
        i32::MAX as i64
    };

    while let Some(&byte) = bytes.get(index) {
        if !byte.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        value = (value * 10) + i64::from(byte - b'0');
        if value > limit {
            return Err(ParseError::OutOfRange);
        }

        index += 1;
    }

    if !saw_digit {
        return Err(ParseError::Invalid);
    }

    if negative {
        if value == 2_147_483_648 {
            Ok(i32::MIN)
        } else {
            Ok(-(value as i32))
        }
    } else {
        Ok(value as i32)
    }
}

fn abort_with_stoi(kind: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{}'", kind);
    eprintln!("  what():  stoi");
    std::process::abort();
}

