use crate::persistent_vector::PersistentVector;

pub fn render_output(n: i32) -> String {
    let mut v = PersistentVector::new();
    let mut i = 0i32;
    while i < n {
        v = v.push_back(i + 1);
        i += 1;
    }

    let first_sum = sum_vector(&v);

    let mut v2 = PersistentVector::new();
    let mut index = 0usize;
    while index < v.size() {
        v2 = v2.push_back(v[index].wrapping_mul(2));
        index += 1;
    }

    let second_sum = sum_vector(&v2);

    format!("{first_sum}\n{second_sum}\n")
}

fn sum_vector(vector: &PersistentVector<i32>) -> i32 {
    let mut sum = 0i32;
    for value in vector.iter().copied() {
        sum = sum.wrapping_add(value);
    }
    sum
}

